const Joi = require('joi');

// Environment validation schema
const envSchema = Joi.object({
  NODE_ENV: Joi.string().valid('development', 'production', 'test').default('development'),
  PORT: Joi.number().default(3000),

  // Database
  DATABASE_URL: Joi.string().uri().required(),

  // External services - validate format but don't expose in error messages
  AWS_ACCESS_KEY_ID: Joi.string().pattern(/^AKIA[0-9A-Z]{16}$/).required(),
  AWS_SECRET_ACCESS_KEY: Joi.string().min(40).required(),

  // API keys
  ANTHROPIC_API_KEY: Joi.string().pattern(/^sk-ant-/).required(),
  STRIPE_SECRET_KEY: Joi.string().pattern(/^sk_(live|test)_/).required(),

  // Security secrets
  JWT_SECRET: Joi.string().min(32).required(),
  SESSION_SECRET: Joi.string().min(32).required(),

  // CORS
  ALLOWED_ORIGINS: Joi.string().default('http://localhost:3000')
}).unknown(true);

// Load and validate environment
const { error, value: envVars } = envSchema.validate(process.env);

if (error) {
  // Don't expose specific validation errors in production
  const errorMessage = process.env.NODE_ENV === 'production' 
    ? 'Configuration validation failed' 
    : error.message;

  throw new Error(`Config validation error: ${errorMessage}`);
}

// Export validated and sanitized configuration
