const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class AWSSecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
  }

  async getSecret(secretName) {
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      if (response.SecretString) {
        return JSON.parse(response.SecretString);
      }

      throw new Error('Secret not found or invalid format');
    } catch (error) {
      console.error('Error retrieving secret:', error);
      throw error;
    }
  }
}

// Usage example
const loadSecretsFromAWS = async () => {
  const secretsManager = new AWSSecretsManager();

  try {
    const databaseSecret = await secretsManager.getSecret('app/database');
    const apiKeys = await secretsManager.getSecret('app/api-keys');

    return {
