      process.exit(1);
    }
  }

  validateSecrets() {
    const requiredSecrets = ['jwtSecret', 'databaseUrl'];
    const missing = requiredSecrets.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  setupMiddleware() {
    this.app.use(helmet());
    this.app.use(cors({
