// Secrets validation and management
const crypto = require('crypto');

// List of required environment variables for production
const REQUIRED_ENV_VARS = [
  'JWT_SECRET',
  'NODE_ENV'
];

// Additional required variables for production
const PRODUCTION_ENV_VARS = [
  'DATABASE_URL',
  'SESSION_SECRET'
];

// Validate environment variables on startup
const validateEnvironment = () => {
  const missingVars = [];

  // Check required variables
  REQUIRED_ENV_VARS.forEach(varName => {
    if (!process.env[varName]) {
      missingVars.push(varName);
    }
  });

  // Check production-specific variables
  if (process.env.NODE_ENV === 'production') {
    PRODUCTION_ENV_VARS.forEach(varName => {
      if (!process.env[varName]) {
        missingVars.push(varName);
      }
    });
  }

  if (missingVars.length > 0) {
    throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
  }

  // Validate JWT secret strength
  if (process.env.JWT_SECRET && process.env.JWT_SECRET.length < 32) {
    console.warn('WARNING: JWT_SECRET is shorter than recommended 32 characters');
  }

  console.log('Environment validation passed');
};

// Generate strong random secret (for development/fallback)
const generateSecret = (length = 64) => {
  return crypto.randomBytes(length).toString('hex');
};

