// Centralized secret management with validation
const Joi = require('joi');

// Secret validation schema
const secretSchema = Joi.object({
  // Required secrets
  NODE_ENV: Joi.string().valid('development', 'production', 'test').required(),
  API_TOKEN: Joi.string().min(32).required(),
  PORT: Joi.number().port().default(3000),

  // Optional secrets (with defaults for development)
  JWT_SECRET: Joi.string().min(32).default('dev-jwt-secret-change-in-production'),
  DATABASE_URL: Joi.string().uri().optional(),

  // External service secrets (validate if present)
  AWS_ACCESS_KEY_ID: Joi.when('NODE_ENV', {
    is: 'production',
    then: Joi.string().required(),
    otherwise: Joi.string().optional()
  }),
  AWS_SECRET_ACCESS_KEY: Joi.when('NODE_ENV', {
    is: 'production',
    then: Joi.string().required(),
    otherwise: Joi.string().optional()
  })
});

class SecretManager {
  constructor() {
    this.secrets = this.loadAndValidateSecrets();
  }

  loadAndValidateSecrets() {
    // Load environment variables
    require('dotenv').config();

    // Extract and validate
    const secrets = {
      NODE_ENV: process.env.NODE_ENV,
      API_TOKEN: process.env.API_TOKEN,
      PORT: process.env.PORT,
      JWT_SECRET: process.env.JWT_SECRET,
      DATABASE_URL: process.env.DATABASE_URL,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY
    };

    const { error, value } = secretSchema.validate(secrets, {
      abortEarly: false,
      allowUnknown: true
    });

    if (error) {
      const missingSecrets = error.details.map(detail => detail.path.join('.'));
      throw new Error(`Secret validation failed: ${missingSecrets.join(', ')}`);
    }

    return value;
  }

  get(key) {
    const value = this.secrets[key];
    if (value === undefined) {
      throw new Error(`Secret '${key}' not found`);
    }
    return value;
  }

  // Static method for easy access
  static getSecret(key) {
    return instance.get(key);
  }
}

// Singleton instance
const instance = new SecretManager();
module.exports = instance;

