// AWS Secrets Manager integration for production
// Only loaded in production environment

const AWS = require('aws-sdk');

class AWSSecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.lastFetch = 0;
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const now = Date.now();
    if (this.cache.has(secretName) && (now - this.lastFetch) < this.cacheTTL) {
      return this.cache.get(secretName);
    }

    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();
      let secret;

      if ('SecretString' in data) {
        secret = data.SecretString;
      } else {
        const buff = Buffer.from(data.SecretBinary, 'base64');
        secret = buff.toString('ascii');
      }

      // Parse JSON if it's a JSON string
      try {
        secret = JSON.parse(secret);
      } catch (e) {
        // Not JSON, keep as string
      }

      // Update cache
      this.cache.set(secretName, secret);
      this.lastFetch = now;

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw error;
    }
  }

  async refreshSecrets() {
    this.cache.clear();
    this.lastFetch = 0;
  }
}

// Export singleton
module.exports = new AWSSecretsManager();

