const fs = require('fs');
const path = require('path');

class SecureConfig {
  constructor() {
    this.secrets = new Map();
    this.requiredSecrets = [
      'JWT_SECRET',
      'DATABASE_URL',
      'SESSION_SECRET'
    ];

    this.optionalSecrets = [
      'PORT',
      'NODE_ENV',
      'BCRYPT_SALT_ROUNDS',
      'ALLOWED_ORIGINS',
      'RATE_LIMIT_WINDOW_MS',
      'RATE_LIMIT_MAX_REQUESTS',
      'LOG_LEVEL'
    ];
  }

  // Load from environment variables with validation
  loadFromEnv() {
    // Check if we're in production and warn about .env usage
    if (process.env.NODE_ENV === 'production' && fs.existsSync('.env')) {
      console.warn('⚠️  WARNING: .env file detected in production environment!');
      console.warn('   Use proper secrets management (AWS Secrets Manager, HashiCorp Vault, etc.)');
    }

    // Load required secrets with validation
    const missingSecrets = [];

    this.requiredSecrets.forEach(secret => {
      const value = process.env[secret];
      if (!value || value.trim() === '') {
        missingSecrets.push(secret);
      } else {
        this.secrets.set(secret, value);
      }
    });

    if (missingSecrets.length > 0) {
      throw new Error(`Missing required environment variables: ${missingSecrets.join(', ')}`);
    }

    // Load optional secrets
    this.optionalSecrets.forEach(secret => {
      const value = process.env[secret];
      if (value) {
        this.secrets.set(secret, value);
      }
    });

    console.log('✅ Environment configuration loaded successfully');
  }

  // Get secret with validation
  get(secretName, defaultValue = null) {
    const value = this.secrets.get(secretName);

    if (value === undefined && defaultValue === null) {
      throw new Error(`Secret '${secretName}' not found and no default provided`);
    }

    return value || defaultValue;
  }

  // Check if secret exists
  has(secretName) {
    return this.secrets.has(secretName);
  }

  // Get all secrets (for debugging, careful with this)
  getAll() {
    return Object.fromEntries(this.secrets);
  }
}

// Singleton instance
const config = new SecureConfig();

// Try to load configuration
try {
  config.loadFromEnv();
} catch (error) {
  console.error('❌ Failed to load configuration:', error.message);
  process.exit(1);
}

module.exports = config;

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class AWSSecretsManager {
  constructor() {
    this.client = null;
    this.cache = new Map();
    this.cacheTime = 5 * 60 * 1000; // 5 minutes cache
  }

  async initialize() {
    try {
      this.client = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1',
        // AWS credentials should be loaded from IAM roles or environment
        // Avoid hardcoding credentials here
      });
