    // Fallback to environment variables for now
    this.loadFromEnvironment();
  }

  async loadFromEnvFile() {
    // Only load .env file if it exists and we're not in production
    const envPath = path.join(__dirname, '..', '.env');
    if (fs.existsSync(envPath)) {
      require('dotenv').config({ path: envPath });
    }
    this.loadFromEnvironment();
  }

  loadFromEnvironment() {
    // Validate and load required secrets
    const requiredSecrets = ['DATABASE_URL', 'SESSION_SECRET'];

    this.secrets = {
      databaseUrl: this.validateSecret('DATABASE_URL', process.env.DATABASE_URL),
      sessionSecret: this.validateSecret('SESSION_SECRET', process.env.SESSION_SECRET),
      awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
      awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      // Add other secrets as needed
    };

    // Validate required secrets
    requiredSecrets.forEach(secret => {
      if (!process.env[secret]) {
        throw new Error(`Missing required secret: ${secret}`);
      }
    });
  }

  validateSecret(name, value) {
    if (!value && this.isProduction) {
      throw new Error(`Missing required secret in production: ${name}`);
    }
    return value;
  }

  getSecret(key) {
    const value = this.secrets[key];
    if (!value && this.isProduction) {
      throw new Error(`Secret not found: ${key}`);
    }
    return value;
  }

  // For security, don't expose all secrets at once
  getDatabaseConfig() {
    return {
      url: this.secrets.databaseUrl,
      // Add other database-specific config
    };
  }
}

