const express = require('express');

const app = express();

// Secure JSON parsing with size limits
app.use(express.json({
  limit: '10kb', // Prevent large payload attacks
  strict: true,  // Only parse objects and arrays
  type: 'application/json' // Only parse JSON content type
}));

// Custom JSON parsing middleware with validation
app.use((req, res, next) => {
  if (req.is('application/json') && req.method === 'POST') {
    try {
      // Validate JSON structure if needed
      if (req.body && typeof req.body === 'object') {
        // Example: Validate no prototype pollution attempts
        const keys = Object.keys(req.body);
        if (keys.some(key => key.includes('__proto__') || key.includes('constructor'))) {
          return res.status(400).json({ error: 'Invalid JSON payload' });
        }
      }
    } catch (error) {
      return res.status(400).json({ error: 'Invalid JSON' });
    }
  }
  next();
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example POST endpoint with validated input
app.post('/users', (req, res) => {
  const { name, email } = req.body;

  // Basic input validation
  if (!name || !email || typeof name !== 'string' || typeof email !== 'string') {
    return res.status(400).json({ error: 'Name and email are required and must be strings' });
  }

  // Email format validation
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  res.json({ 
    message: 'User created successfully', 
    user: { id: Date.now(), name, email }
  });
});

module.exports = app;

