    // Skip logging for health checks to reduce noise
    return req.path === '/health' && res.statusCode < 400;
  },
  stream: {
    write: (message) => {
      // Log to console with security context
      console.log(`[SECURITY] ${new Date().toISOString()} - ${message.trim()}`);

      // Here you would integrate with your security monitoring system
      // Example: send to SIEM, security dashboard, or alerting system
    }
  }
}));

// Custom security event logging
app.use((req, res, next) => {
  // Log potential security events
  const securityHeaders = {
    'user-agent': req.get('user-agent'),
    'x-forwarded-for': req.get('x-forwarded-for'),
    'referer': req.get('referer')
  };

  // Detect potential suspicious activity
  const suspiciousPatterns = [
    '/etc/passwd', 'SELECT *', 'UNION SELECT', 
    'script>', 'javascript:', 'eval('
  ];

  const requestString = JSON.stringify({
    url: req.url,
    method: req.method,
    headers: securityHeaders
  });

  if (suspiciousPatterns.some(pattern => requestString.includes(pattern))) {
    console.warn(`[SECURITY ALERT] Suspicious request detected: ${requestString}`);
    // Would trigger security alert in production
  }

  next();
});

// Response interception for security logging
app.use((req, res, next) => {
  const originalSend = res.send;

  res.send = function(body) {
    // Log responses that might contain sensitive data
    if (res.statusCode >= 400) {
      console.log(`[ERROR] ${req.method} ${req.path} - Status: ${res.statusCode}`);
    }

    // Check for potential information leakage
    if (typeof body === 'string' && body.includes('error') && body.includes('at ')) {
      console.warn(`[SECURITY] Potential stack trace leakage in response to ${req.path}`);
    }

    return originalSend.call(this, body);
  };

  next();
});

